import datetime, json
HOL = set(['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01'])
AY = ['', 'Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
GUN = ['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar']
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nextbd(d):
    d = d + datetime.timedelta(days=1)
    while not isbd(d):
        d = d + datetime.timedelta(days=1)
    return d
def tr(d):
    return str(d.day) + ' ' + AY[d.month] + ' ' + str(d.year) + ' ' + GUN[d.weekday()]
def para(x):
    x = round(float(x) + 1e-9, 2)
    lira = int(x)
    kurus = int(round((x - lira) * 100))
    return (str(lira) + ' lira' + ((' ' + str(kurus) + ' kuruş') if kurus else ''))
def today_now():
    n = str(vars.get('now') or '')
    try:
        dt = datetime.datetime.fromisoformat(n[:16])
    except Exception:
        dt = datetime.datetime(2026, 10, 14, 11, 0)
    return dt

try:
    dt = today_now(); t = dt.date()
    prods = vars.get('acct_json') or vars.get('products')
    if isinstance(prods, str):
        try:
            prods = json.loads(prods)
        except Exception:
            prods = None
    p = prods[0] if isinstance(prods, list) and prods else {}
    if not p:
        p = {}
        for k in ['product_id','type','card_last4','past_due','days_late','minimum_payment','instalment_amount']:
            for key in ['products.0.' + k, 'get_account_response.data.products.0.' + k]:
                if vars.get(key) is not None:
                    p[k] = vars.get(key)
    typ = str(p.get('type') or '')
    full = float(p.get('past_due') or 0)
    dl = int(float(p.get('days_late') or 0))
    if typ == 'credit_card':
        floor = float(p.get('minimum_payment') or 0)
        pname = str(p.get('card_last4') or '') + ' ile biten kredi kartınız'
    elif typ == 'car_loan':
        floor = float(p.get('instalment_amount') or 0); pname = 'taşıt krediniz'
    else:
        floor = float(p.get('instalment_amount') or 0); pname = 'ihtiyaç krediniz'
    late = dl >= 8
    n = 7 if late else 12
    d = t; c = 0
    while c < n:
        d = d + datetime.timedelta(days=1)
        if isbd(d):
            c += 1
    deadline = d
    vars['product_id'] = str(p.get('product_id') or 'p1')
    vars['product_name'] = pname
    vars['full_amount'] = str(round(full, 2)); vars['floor_amount'] = str(round(floor, 2))
    vars['full_tr'] = para(full); vars['floor_tr'] = para(floor)
    vars['days_late'] = str(dl)
    vars['deadline_iso'] = deadline.isoformat(); vars['deadline_tr'] = tr(deadline)
    vars['band'] = 'late' if late else 'early'
    vars['max_attempts'] = '2' if late else '1'
    # this week's last business day
    monday = t - datetime.timedelta(days=t.weekday())
    def lastbd(mon):
        for i in range(4, -1, -1):
            x = mon + datetime.timedelta(days=i)
            if isbd(x):
                return x
        return None
    lw = lastbd(monday)
    if lw is None or lw <= t:
        lw = lastbd(monday + datetime.timedelta(days=7))
    vars['offer1_date_tr'] = tr(lw); vars['offer1_date_iso'] = lw.isoformat()
    rows = []
    x = t
    end = deadline + datetime.timedelta(days=21)
    while x <= end:
        s = x.isoformat() + ' ' + tr(x) + ': '
        if x > deadline:
            s += 'son tarihten sonra -> "Kaydedebileceğim en geç tarih ' + tr(deadline) + '." de ve ' + tr(deadline) + ' öner.'
        elif not isbd(x):
            nb = nextbd(x)
            if nb > deadline:
                s += 'iş günü değil -> en geç tarih ' + tr(deadline) + ', onu öner.'
            else:
                s += ('banka tatili' if x.weekday() < 5 else 'hafta sonu') + ' -> kabul etme, bir sonraki iş günü ' + tr(nb) + ' öner.'
        else:
            s += 'uygun, kabul edilebilir.'
        rows.append(s)
        x = x + datetime.timedelta(days=1)
    rel = ['bugün = ' + tr(t), 'yarın = ' + tr(t + datetime.timedelta(days=1)), 'öbür gün = ' + tr(t + datetime.timedelta(days=2))]
    for i in range(7):
        rel.append('bu ' + GUN[i] + ' = ' + tr(monday + datetime.timedelta(days=i)))
        rel.append('haftaya ' + GUN[i] + ' = ' + tr(monday + datetime.timedelta(days=7 + i)))
    rel.append('bu hafta sonu / hafta sonu = ' + tr(monday + datetime.timedelta(days=5)))
    vars['date_table'] = '\n'.join(rows)
    vars['rel_table'] = '\n'.join(rel)
    vars['attempts_used'] = '0'
    vars['acct_state'] = 'ok' if full > 0 else 'missing'
except Exception as e:
    vars['acct_state'] = 'missing'
    vars['date_table'] = ''; vars['rel_table'] = ''

